import fs from 'node:fs';import {A,assets,c,root,createCanvas} from './tests/load-assets.mjs';import {createJangmokEnvironment} from './environment.mjs';import {NativeHomeSession} from './session.mjs';import {renderNativeHome} from './render.mjs';
const masks=Object.fromEntries(Object.entries(c.masks).map(([k,v])=>[k,new Uint8Array(fs.readFileSync(new URL(v.path,root)))])),travel=JSON.parse(fs.readFileSync(new URL('travel-routes.json',root))),env=createJangmokEnvironment(A),s=new NativeHomeSession({contract:c,homeId:'upper',masks}),cv=createCanvas(960,540),out=new URL('./recovery-proofs/',root),rows=[];fs.mkdirSync(out,{recursive:true});
function walk(path){if(s.foot.join()!=path[0].join())throw Error('START');for(const p of path.slice(1)){const[x,y]=s.foot;if(!s.move(p[0]<x?'left':p[0]>x?'right':p[1]<y?'up':'down').ok)throw Error('UNSUPPORTED')}}
function shot(n){s.stopGait();const r=renderNativeHome(cv.getContext('2d'),{contract:c,assets,environment:env,status:s.snapshot()});fs.writeFileSync(new URL(n+'.png',out),cv.toBuffer('image/png'));rows.push({file:n+'.png',status:s.snapshot(),render:r});globalThis.gc?.()}
s.setDoorState('OPEN','upper');s.setDoorState('OPEN','family');s.setDoorState('OPEN','coastal');env.setTime(1320);walk(travel.routes.upper__upper);s.face('up');shot('01_UPPER_NIGHT');await s.action();s.releaseAction();shot('02_UPPER_INSIDE');walk(c.floors.upper_1F.routes.entryArrival_stair);await s.action();s.releaseAction();shot('03_UPPER_2F');walk(c.floors.upper_2F.routes.stairArrival_stair);await s.action();s.releaseAction();walk(c.floors.upper_1F.routes.stairArrival_entry);s.face('down');await s.action();s.releaseAction();walk(travel.routes.upper__family);s.face('up');shot('04_FAMILY_NIGHT');await s.action();s.releaseAction();shot('05_FAMILY_INSIDE');walk(c.floors.family_1F.routes.entryArrival_entry);s.face('down');await s.action();s.releaseAction();walk(travel.routes.family__coastal);s.face('up');shot('06_COASTAL_NIGHT');await s.action();s.releaseAction();shot('07_COASTAL_INSIDE');walk(c.floors.coastal_1F.routes.entryArrival_entry);s.face('down');await s.action();s.releaseAction();shot('08_COASTAL_RETURN');walk(travel.routes.coastal__upper);s.face('up');env.setTime(720);shot('09_TOUR_RETURN_UPPER_DAY');
fs.writeFileSync(new URL('PROOF_METADATA.json',out),JSON.stringify({status:'NEW_OFFLINE_SAME_SESSION_TOUR',actualBrowser:false,rows},null,2));
